    pub created_at: String,
}

pub struct ConversationFeedbackAuthorizationRecord {
    pub consent: ConversationFeedbackAuthorization,
    /// Application validates live pixels and terminal Artifact identity. Storage
    /// binds the embedded saved message and optimistic image feedback sequence.
    pub context: Value,
    /// Server-resolved display metadata; never refresh old consent from new settings.
    pub summary: Value,
    pub grant: ConversationCallGrant,
}

enum RawProposal {
    Draft {
        goal: String,
        kind: annotagent_core::TaskKind,
        labels: Vec<String>,
        multi_label: bool,
        attributes: BTreeMap<String, annotagent_core::AttributeDefinition>,
        boundary_rules: Vec<String>,
        rationale: String,
    },
    Clarify {
        goal: String,
        question: String,
        rationale: String,
    },
}

pub struct QueuedPlanningAuthorization {
    pub conversation_id: Uuid,
    pub message_id: Uuid,
    pub previous_grant_id: Option<Uuid>,
    pub grant: ConversationCallGrant,
    pub model_id: ModelProfileId,
    /// Server-computed exact model request digest, not merely the consent hash.
    pub request_hash: String,
}

pub struct ConversationSchemaDefinition {
    pub goal: String,
    pub task: TaskConfig,
    pub boundary_rules: Vec<String>,
}

pub struct ConversationSchemaDraft {
    pub id: Uuid,
    pub task_id: Uuid,
    pub source_call_id: Option<Uuid>,
    /// Human confirmation command; model-assisted future forks retain their proposal
    /// provenance in the linked future-Schema record. Never an inference receipt.
    pub source_request_id: Option<Uuid>,
    pub base_schema_revision: String,
    pub revision: u64,
    pub definition: ConversationSchemaDefinition,
}

pub struct ConversationExportEvent {
    pub sequence: i64,
    pub export_id: Uuid,
    pub kind: String,
}

pub struct ConversationImageRef {
    pub image_id: String,
    pub sha256: String,
}

pub enum ConversationSelectionRef {
    StopRequest {
        task_id: Option<Uuid>,
    },
    SampleCandidate {
        task_id: Uuid,
        project_schema_revision: String,
        draft_id: String,
        draft_revision: u64,
        sample_test_id: String,
        candidate_id: String,
        source_artifact_id: Uuid,
    },
}

pub struct ConversationMessage {
    pub conversation_id: Uuid,
    pub sequence: i64,
    pub input: ConversationMessageInput,
}

pub enum ConversationSendMode {
    Plan,
    Execute,
}

pub struct ConversationSendInput {
    pub message: ConversationMessageInput,
    pub task_id: Option<Uuid>,
    pub schema_revision: String,
    /// Optional observed preference for CAS admission; absent for older clients.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub agent_model: Option<crate::ConversationAgentModel>,
    /// Missing means a legacy command, not implicit execution permission.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<ConversationSendMode>,
}

pub enum ConversationSendDisposition {
    NewTask,
    TaskMessage,
    CandidateFeedback,
}

pub struct ConversationSendReceipt {
    pub message: ConversationMessage,
    pub task_id: Uuid,
    pub disposition: ConversationSendDisposition,
    /// None means a historical receipt predating model snapshots, not default.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub agent_model: Option<crate::ConversationAgentModel>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<ConversationSendMode>,
    /// Resolved at Send when setup exists. Historical/unconfigured messages have None.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolved_agent_model_id: Option<annotagent_core::ModelProfileId>,

}

pub struct SelectConversationTask {
    pub request_id: Uuid,
    pub expected_revision: u64,
    pub task_id: Uuid,
}

pub struct ConversationTaskSelection {
    pub revision: u64,
    pub task_id: Option<Uuid>,
}

pub struct ConversationStopTargetRef {
